nor":107500},{"maxGrams":1000,"thbMinor":119500},{"maxGrams":1100,"thbMinor":131000},{"maxGrams":1200,"thbMinor":143000},{"maxGrams":1300,"thbMinor":154500},{"maxGrams":1400,"thbMinor":166000},{"maxGrams":1500,"thbMinor":178000},{"maxGrams":1600,"thbMinor":189500},{"maxGrams":1700,"thbMinor":201500},{"maxGrams":1800,"thbMinor":213000},{"maxGrams":1900,"thbMinor":224500},{"maxGrams":2000,"thbMinor":236500}],"BT:epacket":[{"maxGrams":100,"thbMinor":16000},{"maxGrams":200,"thbMinor":19500},{"maxGrams":300,"thbMinor":24000},{"maxGrams":400,"thbMinor":28500},{"maxGrams":500,"thbMinor":33000},{"maxGrams":600,"thbMinor":37000},{"maxGrams":700,"thbMinor":41000},{"maxGrams":800,"thbMinor":45000},{"maxGrams":900,"thbMinor":49000},{"maxGrams":1000,"thbMinor":53000},{"maxGrams":1100,"thbMinor":56500},{"maxGrams":1200,"thbMinor":60000},{"maxGrams":1300,"thbMinor":63500},{"maxGrams":1400,"thbMinor":67500},{"maxGrams":1500,"thbMinor":72000},{"maxGrams":1600,"thbMinor":76000},{"maxGrams":1700,"thbMinor":80000},{"maxGrams":1800,"thbMinor":84000},{"maxGrams":1900,"thbMinor":88500},{"maxGrams":2000,"thbMinor":92500}],"BR:epacket":[{"maxGrams":100,"thbMinor":26000},{"maxGrams":200,"thbMinor":32500},{"maxGrams":300,"thbMinor":39000},{"maxGrams":400,"thbMinor":49000},{"maxGrams":500,"thbMinor":61000},{"maxGrams":600,"thbMinor":72500},{"maxGrams":700,"thbMinor":84000},{"maxGrams":800,"thbMinor":96000},{"maxGrams":900,"thbMinor":107500},{"maxGrams":1000,"thbMinor":119500},{"maxGrams":1100,"thbMinor":131000},{"maxGrams":1200,"thbMinor":143000},{"maxGrams":1300,"thbMinor":154500},{"maxGrams":1400,"thbMinor":166000},{"maxGrams":1500,"thbMinor":178000},{"maxGrams":1600,"thbMinor":189500},{"maxGrams":1700,"thbMinor":201500},{"maxGrams":1800,"thbMinor":213000},{"maxGrams":1900,"thbMinor":224500},{"maxGrams":2000,"thbMinor":236500}],"KH:epacket":[{"maxGrams":100,"thbMinor":16000},{"maxGrams":200,"thbMinor":19500},{"maxGrams":300,"thbMinor":24000},{"maxGrams":400,"thbMinor":28500},{"maxGrams":500,